  for (const arrival of arrivals) {
    if (arrival.rel !== relName || arrival.sign !== "add") continue;
    const key = JSON.stringify(arrival.row);
    if (seen.has(key)) continue;
    seen.add(key);
    occurrences.push(arrival);
  }
  return occurrences;
